import React, { useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import blogData from '../data/blogData.json';
import './Blog.css';

const BlogPost = () => {
  const { slug } = useParams();
  const post = blogData.find(p => p.slug === slug);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [slug]);

  if (!post) {
    return (
      <div className="page container" style={{ paddingTop: '150px', textAlign: 'center', minHeight: '100vh' }}>
        <h2>Post not found.</h2>
        <Link to="/blog" className="interactive link-accent" style={{ marginTop: '2rem', display: 'inline-block' }}>Return to Blog</Link>
      </div>
    );
  }

  const date = new Date(post.published).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });

  return (
    <div className="page blog-post-container">
      <Link to="/blog" className="back-to-blog">Back to all posts</Link>
      
      <div className="blog-post-header">
        <span className="blog-post-date">{date}</span>
        <h1 className="blog-post-title">{post.title}</h1>
      </div>

      {post.featuredImage && (
        <motion.img 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          src={post.featuredImage} 
          alt={post.title} 
          className="blog-post-featured-image" 
        />
      )}

      <motion.div 
        className="blog-post-content"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.8, delay: 0.2 }}
        dangerouslySetInnerHTML={{ __html: post.content }}
      />
    </div>
  );
};

export default BlogPost;
